163	func cmdRegister(args []string, w io.Writer) error {
164		var opts cmdOptions
165		var id, name, location string
166		fs := newFlagSet("register", &opts)
167		fs.StringVar(&id, "asset-id", "", "企业资产编号（必填，同一数据目录内唯一）")
