215		}
216		fmt.Fprintf(w, "共 %d 项资产:\n", len(assets))
217		for _, a := range assets {
218			fmt.Fprintf(w, "%s\t%s\t%s\t%s\n", a.ID, a.Name, a.Location, a.Status)
219		}
220		return nil
221	}
222	
223	func cmdDetail(args []string, w io.Writer) error {
224		var opts cmdOptions
225		var id string
226		fs := newFlagSet("detail", &opts)
227		fs.StringVar(&id, "asset-id", "", "企业资产编号（必填）")
228		if err := parseFlags(fs, args); err != nil {
229			return err
230		}
231		if err := requireFlag(fs, id, "asset-id"); err != nil {
232			return err
233		}
234		s, err := openStore(opts.dataDir)
235		if err != nil {
236			return err
237		}
238		asset := s.findAsset(id)
239		if asset == nil {
240			return fmt.Errorf("未知资产编号 %q", id)
241		}
242		openTicket := s.openTicketOf(asset.ID)
243		fmt.Fprintf(w, "资产编号: %s\n", asset.ID)
244		fmt.Fprintf(w, "名称: %s\n", asset.Name)
245		fmt.Fprintf(w, "位置: %s\n", asset.Location)
246		fmt.Fprintf(w, "当前状态: %s\n", asset.Status)
247		if openTicket == nil {
248			fmt.Fprintln(w, "未关闭工单: 无")
249		} else {
250			fmt.Fprintf(w, "未关闭工单: %s\n", openTicket.ID)
251		}
252		return nil
253	}
254	
255	func cmdReport(args []string, w io.Writer) error {
256		var opts cmdOptions
257		var assetID, description, requestID string
258		fs := newFlagSet("report", &opts)
259		fs.StringVar(&assetID, "asset-id", "", "企业资产编号（必填）")
260		fs.StringVar(&description, "description", "", "故障描述（必填）")
261		fs.StringVar(&requestID, "request-id", "", "调用方提供的非空请求标识，用于报修去重（必填）")
262		if err := parseFlags(fs, args); err != nil {
263			return err
264		}
265		if err := requireFlag(fs, assetID, "asset-id"); err != nil {
266			return err
267		}
268		if err := requireFlag(fs, description, "description"); err != nil {
269			return err
270		}
271		if err := requireFlag(fs, requestID, "request-id"); err != nil {
272			return err
273		}
274	
275		s, err := openStore(opts.dataDir)
276		if err != nil {
277			return err
278		}
279		ticket, replayed, err := s.report(assetID, description, requestID)
280		if err != nil {
281			return err
282		}
283		if !replayed {
284			if err := s.save(); err != nil {
285				return err
286			}
287			fmt.Fprintf(w, "工单编号: %s\n", ticket.ID)
288		} else {
289			fmt.Fprintf(w, "该请求标识已提交过，返回原工单，未重复创建。\n")
290			fmt.Fprintf(w, "工单编号: %s（既有工单）\n", ticket.ID)
291		}
292		fmt.Fprintf(w, "资产编号: %s\n", ticket.AssetID)
293		fmt.Fprintf(w, "工单状态: %s\n", ticket.Status)
294		return nil
295	}
296	
297	func cmdClose(args []string, w io.Writer) error {
298		var opts cmdOptions
299		var ticketID, result string
300		fs := newFlagSet("close", &opts)
301		fs.StringVar(&ticketID, "ticket-id", "", "要关闭的工单编号（必填）")
302		fs.StringVar(&result, "repair-result", "", "维修结果（必填）")
303		if err := parseFlags(fs, args); err != nil {
304			return err
305		}
306		if err := requireFlag(fs, ticketID, "ticket-id"); err != nil {
307			return err
308		}
309		if err := requireFlag(fs, result, "repair-result"); err != nil {
310			return err
311		}
312	
313		s, err := openStore(opts.dataDir)
314		if err != nil {
315			return err
316		}
317		ticket, asset, err := s.closeTicket(ticketID, result)
318		if err != nil {
319			return err
320		}
321		if err := s.save(); err != nil {
322			return err
323		}
324		fmt.Fprintf(w, "工单 %s 已关闭。\n", ticket.ID)
325		fmt.Fprintf(w, "资产 %s 当前状态: %s\n", asset.ID, asset.Status)
326		return nil
327	}
328	
329	func cmdHistory(args []string, w io.Writer) error {
330		var opts cmdOptions
331		var id string
332		fs := newFlagSet("history", &opts)
333		fs.StringVar(&id, "asset-id", "", "企业资产编号（必填）")
334		if err := parseFlags(fs, args); err != nil {
335			return err
336		}
337		if err := requireFlag(fs, id, "asset-id"); err != nil {
338			return err
339		}
340		s, err := openStore(opts.dataDir)
341		if err != nil {
342			return err
343		}
344		if s.findAsset(id) == nil {
345			return fmt.Errorf("未知资产编号 %q", id)
346		}
347		events := s.eventsOf(id)
348		if len(events) == 0 {
349			fmt.Fprintf(w, "资产 %s 暂无维修履历。\n", id)
350			return nil
351		}
352		fmt.Fprintf(w, "资产 %s 维修履历（共 %d 条）:\n", id, len(events))
353		for _, e := range events {
354			fmt.Fprintf(w, "[%s] %s 工单 %s: %s\n",
355				e.Time.Format("2006-01-02T15:04:05Z07:00"), e.Kind, e.TicketID, e.Content)
356		}
357		return nil
358	}
