1	package main
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"errors"
7		"fmt"
8		"os"
9		"path/filepath"
10		"sort"
11		"time"
12	)
13	
14	// 资产状态、工单状态与履历类型。
15	const (
16		statusAvailable = "可用"
17		statusRepairing = "维修中"
18		ticketOpen      = "未关闭"
19		ticketClosed    = "已关闭"
20	
21		eventReport = "报修"
22		eventClose  = "关闭"
23	
24		storeVersion = 1
25		dataFileName = "caretrack.json"
26	)
27	
28	var (
29		errNotFound = errors.New("not found")
30		errConflict = errors.New("conflict")
31	)
32	
33	// Asset 为登记的设备资产，ID 即企业资产编号。
34	type Asset struct {
35		ID       string `json:"id"`
36		Name     string `json:"name"`
37		Location string `json:"location"`
38		Status   string `json:"status"`
39	}
40	
41	// Ticket 为维修工单。
42	type Ticket struct {
43		ID          string `json:"id"`
44		AssetID     string `json:"asset_id"`
45		Description string `json:"description"`
46		RequestID   string `json:"request_id"`
47		Status      string `json:"status"`
48		Result      string `json:"result,omitempty"`
49		CreatedAt   string `json:"created_at"`
50		ClosedAt    string `json:"closed_at,omitempty"`
51	}
52	
53	// Event 为履历条目（报修/关闭），Seq 决定操作发生顺序。
54	type Event struct {
55		Seq      int       `json:"-"`
56		AssetID  string    `json:"-"`
57		TicketID string    `json:"-"`
58		Kind     string    `json:"-"`
59		Content  string    `json:"-"`
60		Time     time.Time `json:"-"`
61	}
62	
63	// eventJSON 与 Event 对应，时间以 RFC3339 文本持久化。
64	type eventJSON struct {
65		Seq      int    `json:"seq"`
66		AssetID  string `json:"asset_id"`
67		TicketID string `json:"ticket_id"`
68		Kind     string `json:"kind"`
69		Content  string `json:"content"`
70		Time     string `json:"time"`
71	}
72	
73	func (e Event) toJSON() eventJSON {
74		return eventJSON{
75			Seq: e.Seq, AssetID: e.AssetID, TicketID: e.TicketID,
76			Kind: e.Kind, Content: e.Content, Time: e.Time.Format(time.RFC3339),
77		}
78	}
79	
80	func (e eventJSON) toEvent() (Event, error) {
81		t, err := time.Parse(time.RFC3339, e.Time)
82		if err != nil {
83			return Event{}, fmt.Errorf("履历时间格式无效 %q: %w", e.Time, err)
84		}
85		return Event{
86			Seq: e.Seq, AssetID: e.AssetID, TicketID: e.TicketID,
87			Kind: e.Kind, Content: e.Content, Time: t,
88		}, nil
89	}
90	
91	// requestBinding 记录请求标识与具体报修的绑定，用于去重与冲突拒绝；
92	// 它既不是资产编号也不是工单编号。
93	type requestBinding struct {
94		RequestID   string `json:"request_id"`
95		AssetID     string `json:"asset_id"`
96		Description string `json:"description"`
97		TicketID    string `json:"ticket_id"`
98	}
99	
100	// storeData 是一次成功写操作共同生效的完整业务数据。
101	type storeData struct {
102		Version       int              `json:"version"`
103		Assets        []*Asset         `json:"assets"`
104		Tickets       []*Ticket        `json:"tickets"`
105		Events        []Event          `json:"-"`
106		EventsJSON    []eventJSON      `json:"events"`
107		Requests      []requestBinding `json:"requests"`
108		NextTicketSeq int              `json:"next_ticket_seq"`
109	}
110	
111	type store struct {
112		dir  string
113		data *storeData
114		now  func() time.Time
115	}
116	
117	func newStoreData() *storeData {
118		return &storeData{
119			Version:       storeVersion,
120			Assets:        []*Asset{},
121			Tickets:       []*Ticket{},
122			Events:        []Event{},
123			EventsJSON:    []eventJSON{},
124			Requests:      []requestBinding{},
125			NextTicketSeq: 1,
126		}
127	}
128	
129	// openStore 打开数据目录：目录/文件不存在时视为空库（首次保存时初始化）；
130	// 已有文件为空或无法解析时报告错误并保留原文件，绝不当空库覆盖。
131	func openStore(dir string) (*store, error) {
132		path := filepath.Join(dir, dataFileName)
133		raw, err := os.ReadFile(path)
134		if err != nil {
135			if errors.Is(err, os.ErrNotExist) {
136				return &store{dir: dir, data: newStoreData(), now: time.Now}, nil
137			}
138			return nil, fmt.Errorf("读取数据文件失败: %w", err)
139		}
140		if len(bytes.TrimSpace(raw)) == 0 {
141			return nil, fmt.Errorf("数据文件 %s 已损坏：文件为空（原文件已保留，未做任何修改）", path)
142		}
143		var d storeData
144		if err := json.Unmarshal(raw, &d); err != nil {
145			return nil, fmt.Errorf("数据文件 %s 已损坏：%w（原文件已保留，未做任何修改）", path, err)
146		}
147		if err := validateData(&d); err != nil {
148			return nil, fmt.Errorf("数据文件 %s 已损坏：%w（原文件已保留，未做任何修改）", path, err)
149		}
150		d.Events = make([]Event, len(d.EventsJSON))
151		for i, ej := range d.EventsJSON {
152			ev, err := ej.toEvent()
153			if err != nil {
154				return nil, fmt.Errorf("数据文件 %s 已损坏：%w（原文件已保留，未做任何修改）", path, err)
155			}
156			d.Events[i] = ev
157		}
158		return &store{dir: dir, data: &d, now: time.Now}, nil
159	}
160	
161	func validateData(d *storeData) error {
162		if d.Version != storeVersion {
163			return fmt.Errorf("不支持的数据版本 %d", d.Version)
164		}
165		if d.Assets == nil || d.Tickets == nil || d.Requests == nil || d.EventsJSON == nil {
166			return errors.New("缺少必要的数据段")
167		}
168		seenAssets := map[string]bool{}
169		for _, a := range d.Assets {
170			if a == nil || a.ID == "" || a.Name == "" || a.Location == "" {
171				return errors.New("存在字段不完整的资产记录")
172			}
173			if a.Status != statusAvailable && a.Status != statusRepairing {
174				return fmt.Errorf("资产 %s 状态无效", a.ID)
175			}
176			if seenAssets[a.ID] {
177				return fmt.Errorf("资产编号 %s 重复", a.ID)
178			}
179			seenAssets[a.ID] = true
180		}
181		seenTickets := map[string]bool{}
182		for _, t := range d.Tickets {
183			if t == nil || t.ID == "" || t.AssetID == "" || t.RequestID == "" || t.CreatedAt == "" {
184				return errors.New("存在字段不完整的工单记录")
185			}
186			if t.Status != ticketOpen && t.Status != ticketClosed {
187				return fmt.Errorf("工单 %s 状态无效", t.ID)
188			}
189			if !seenAssets[t.AssetID] {
190				return fmt.Errorf("工单 %s 引用了不存在的资产", t.ID)
191			}
192			if t.Status == ticketClosed && (t.Result == "" || t.ClosedAt == "") {
193				return fmt.Errorf("工单 %s 缺少关闭信息", t.ID)
194			}
195			if seenTickets[t.ID] {
196				return fmt.Errorf("工单编号 %s 重复", t.ID)
197			}
198			seenTickets[t.ID] = true
199		}
200		seenReq := map[string]bool{}
201		for _, r := range d.Requests {
202			if r.RequestID == "" || r.AssetID == "" || r.Description == "" || r.TicketID == "" {
203				return errors.New("存在字段不完整的请求去重记录")
204			}
205			if !seenAssets[r.AssetID] || !seenTickets[r.TicketID] {
206				return fmt.Errorf("请求标识 %s 的绑定记录不完整", r.RequestID)
207			}
208			if seenReq[r.RequestID] {
209				return fmt.Errorf("请求标识 %s 重复", r.RequestID)
210			}
211			seenReq[r.RequestID] = true
212		}
213		for _, ej := range d.EventsJSON {
214			if ej.AssetID == "" || ej.TicketID == "" || ej.Kind == "" || ej.Time == "" {
215				return errors.New("存在字段不完整的履历记录")
216			}
217			if !seenAssets[ej.AssetID] || !seenTickets[ej.TicketID] {
218				return errors.New("履历记录引用了不存在的资产或工单")
219			}
220			if ej.Kind != eventReport && ej.Kind != eventClose {
221				return fmt.Errorf("履历事件类型无效: %q", ej.Kind)
222			}
223		}
224		return nil
225	}
226	
227	// save 将全部业务数据一次性原子写入：先写同目录临时文件，fsync 后 rename
228	// 覆盖正式文件。业务校验均在调用 save 之前完成；写入失败时原文件保持不变。
229	func (s *store) save() error {
230		s.data.EventsJSON = make([]eventJSON, len(s.data.Events))
231		for i, e := range s.data.Events {
232			s.data.EventsJSON[i] = e.toJSON()
233		}
234		var buf bytes.Buffer
235		enc := json.NewEncoder(&buf)
236		enc.SetIndent("", "  ")
237		if err := enc.Encode(s.data); err != nil {
238			return fmt.Errorf("编码数据失败: %w", err)
239		}
240		if err := os.MkdirAll(s.dir, 0o755); err != nil {
241			return fmt.Errorf("创建数据目录失败: %w", err)
242		}
243		path := filepath.Join(s.dir, dataFileName)
244		tmp, err := os.CreateTemp(s.dir, ".caretrack-*.tmp")
245		if err != nil {
246			return fmt.Errorf("创建临时数据文件失败: %w", err)
247		}
248		tmpName := tmp.Name()
249		abort := func(err error) error {
250			_ = tmp.Close()
251			_ = os.Remove(tmpName)
252			return err
253		}
254		if _, err := tmp.Write(buf.Bytes()); err != nil {
255			abort(nil)
256			return fmt.Errorf("写入数据失败: %w", err)
257		}
258		if err := tmp.Sync(); err != nil {
259			abort(nil)
260			return fmt.Errorf("写入数据失败: %w", err)
261		}
262		if err := tmp.Close(); err != nil {
263			_ = os.Remove(tmpName)
264			return fmt.Errorf("写入数据失败: %w", err)
265		}
266		if err := os.Rename(tmpName, path); err != nil {
267			_ = os.Remove(tmpName)
268			return fmt.Errorf("保存数据失败: %w", err)
269		}
270		return nil
271	}
272	
273	func (s *store) findAsset(id string) *Asset {
274		for _, a := range s.data.Assets {
275			if a.ID == id {
276				return a
277			}
278		}
279		return nil
280	}
281	
282	func (s *store) findTicket(id string) *Ticket {
283		for _, t := range s.data.Tickets {
284			if t.ID == id {
285				return t
286			}
287		}
288		return nil
289	}
290	
291	func (s *store) findRequest(requestID string) *requestBinding {
292		for i := range s.data.Requests {
293			if s.data.Requests[i].RequestID == requestID {
294				return &s.data.Requests[i]
295			}
296		}
297		return nil
298	}
299	
300	func (s *store) openTicketOf(assetID string) *Ticket {
301		for _, t := range s.data.Tickets {
302			if t.AssetID == assetID && t.Status == ticketOpen {
303				return t
304			}
305		}
306		return nil
307	}
308	
309	func (s *store) eventsOf(assetID string) []Event {
310		out := make([]Event, 0)
311		for _, e := range s.data.Events {
312			if e.AssetID == assetID {
313				out = append(out, e)
314			}
315		}
316		sort.SliceStable(out, func(i, j int) bool { return out[i].Seq < out[j].Seq })
317		return out
318	}
319	
320	func (s *store) nextEventSeq() int {
321		maxSeq := 0
322		for _, e := range s.data.Events {
323			if e.Seq > maxSeq {
324				maxSeq = e.Seq
325			}
326		}
327		return maxSeq + 1
328	}
329	
330	func (s *store) addEvent(assetID, ticketID, kind, content string) {
331		s.data.Events = append(s.data.Events, Event{
332			Seq:      s.nextEventSeq(),
333			AssetID:  assetID,
334			TicketID: ticketID,
335			Kind:     kind,
336			Content:  content,
337			Time:     s.now(),
338		})
339	}
340	
341	func (s *store) registerAsset(id, name, location string) (*Asset, error) {
342		if s.findAsset(id) != nil {
343			return nil, fmt.Errorf("%w: 资产编号 %q 已存在", errConflict, id)
344		}
345		a := &Asset{ID: id, Name: name, Location: location, Status: statusAvailable}
346		s.data.Assets = append(s.data.Assets, a)
347		return a, nil
348	}
349	
350	// report 创建报修工单。返回 (工单, 是否为去重重放, 错误)。
351	// 所有失败路径都不修改任何业务数据，也不会绑定新的请求标识。
352	func (s *store) report(assetID, description, requestID string) (*Ticket, bool, error) {
353		// 已有绑定：相同资产+描述 => 返回原工单（无论其是否已关闭、是否已有新工单）；
354		// 资产或描述不同 => 拒绝。
355		if r := s.findRequest(requestID); r != nil {
356			if r.AssetID != assetID || r.Description != description {
357				return nil, false, fmt.Errorf(
358					"%w: 请求标识 %q 已用于资产 %q 的另一笔报修，不能搭配不同的资产编号或故障描述",
359					errConflict, requestID, r.AssetID)
360			}
361			t := s.findTicket(r.TicketID)
362			if t == nil {
363				return nil, false, fmt.Errorf("数据内部错误：请求标识 %q 绑定的工单不存在", requestID)
364			}
365			return t, true, nil
366		}
367	
368		asset := s.findAsset(assetID)
369		if asset == nil {
370			return nil, false, fmt.Errorf("%w: 未知资产编号 %q", errNotFound, assetID)
371		}
372		if t := s.openTicketOf(assetID); t != nil {
373			return nil, false, fmt.Errorf("%w: 资产 %s 已有未关闭工单 %s", errConflict, assetID, t.ID)
374		}
375	
376		seq := s.data.NextTicketSeq
377		s.data.NextTicketSeq++
378		t := &Ticket{
379			ID:          fmt.Sprintf("T%04d", seq),
380			AssetID:     assetID,
381			Description: description,
382			RequestID:   requestID,
383			Status:      ticketOpen,
384			CreatedAt:   s.now().Format(time.RFC3339),
385		}
386		s.data.Tickets = append(s.data.Tickets, t)
387		s.data.Requests = append(s.data.Requests, requestBinding{
388			RequestID:   requestID,
389			AssetID:     assetID,
390			Description: description,
391			TicketID:    t.ID,
392		})
393		asset.Status = statusRepairing
394		s.addEvent(assetID, t.ID, eventReport, description)
395		return t, false, nil
396	}
397	
398	// closeTicket 关闭未关闭工单并把资产恢复为可用。
399	func (s *store) closeTicket(ticketID, result string) (*Ticket, *Asset, error) {
400		t := s.findTicket(ticketID)
401		if t == nil {
402			return nil, nil, fmt.Errorf("%w: 未知工单编号 %q", errNotFound, ticketID)
403		}
404		if t.Status != ticketOpen {
405			return nil, nil, fmt.Errorf("%w: 工单 %s 已关闭，不能重复关闭", errConflict, ticketID)
406		}
407		asset := s.findAsset(t.AssetID)
408		if asset == nil {
409			return nil, nil, fmt.Errorf("数据内部错误：工单 %s 引用的资产不存在", ticketID)
410		}
411		t.Status = ticketClosed
412		t.Result = result
413		t.ClosedAt = s.now().Format(time.RFC3339)
414		asset.Status = statusAvailable
415		s.addEvent(asset.ID, t.ID, eventClose, result)
416		return t, asset, nil
417	}
