1	package main
2	
3	import (
4		"errors"
5		"os"
6		"path/filepath"
7		"strings"
8		"testing"
9		"time"
10	)
11	
12	func newTestStore(t *testing.T) *store {
13		t.Helper()
14		s, err := openStore(t.TempDir())
15		if err != nil {
16			t.Fatalf("openStore: %v", err)
17		}
18		clock := time.Unix(1_700_000_000, 0)
19		s.now = func() time.Time {
20			clock = clock.Add(time.Second)
21			return clock
22		}
23		return s
24	}
25	
26	func saveAndReopen(t *testing.T, s *store) *store {
27		t.Helper()
28		if err := s.save(); err != nil {
29			t.Fatalf("save: %v", err)
30		}
31		s2, err := openStore(s.dir)
32		if err != nil {
33			t.Fatalf("reopen: %v", err)
34		}
35		s2.now = s.now
36		return s2
37	}
38	
39	func TestRegisterAndList(t *testing.T) {
40		s := newTestStore(t)
41		if _, err := s.registerAsset("EQ-1", "打印机", "一楼大厅"); err != nil {
42			t.Fatalf("register: %v", err)
43		}
44		a2, err := s.registerAsset("EQ-2", "空调", "二楼会议室")
45		if err != nil {
46			t.Fatalf("register: %v", err)
47		}
48		if a2.Status != statusAvailable {
49			t.Fatalf("新资产状态 = %q, 想得到 %q", a2.Status, statusAvailable)
50		}
51		if _, err := s.registerAsset("EQ-1", "x", "y"); !errors.Is(err, errConflict) {
52			t.Fatalf("重复编号应冲突，得到 %v", err)
53		}
54		if len(s.data.Assets) != 2 {
55			t.Fatalf("失败登记不应产生记录，资产数 = %d", len(s.data.Assets))
56		}
57	}
58	
59	func TestReportLifecycleAndDedup(t *testing.T) {
60		s := newTestStore(t)
61	
62		// 未知资产报修失败。
63		if _, _, err := s.report("NOPE", "坏了", "req-1"); !errors.Is(err, errNotFound) {
64			t.Fatalf("未知资产应失败，得到 %v", err)
65		}
66		if s.findRequest("req-1") != nil {
67			t.Fatal("失败的报修不应绑定请求标识")
68		}
69	
70		if _, err := s.registerAsset("EQ-1", "打印机", "一楼"); err != nil {
71			t.Fatal(err)
72		}
73		tk, replay, err := s.report("EQ-1", "卡纸", "req-1")
74		if err != nil || replay {
75			t.Fatalf("首次报修: ticket=%v replay=%v err=%v", tk, replay, err)
76		}
77		if tk.ID != "T0001" {
78			t.Fatalf("首单编号 = %q, 想得到 T0001", tk.ID)
79		}
80		if got := s.findAsset("EQ-1").Status; got != statusRepairing {
81			t.Fatalf("报修后资产状态 = %q", got)
82		}
83	
84		// 同资产已有未关闭工单，新报修失败。
85		if _, _, err := s.report("EQ-1", "又坏了", "req-2"); !errors.Is(err, errConflict) {
86			t.Fatalf("已有未关闭工单时应失败，得到 %v", err)
87		}
88		if s.findRequest("req-2") != nil {
89			t.Fatal("失败的报修不应绑定请求标识 req-2")
90		}
91	
92		// 相同标识+资产+描述重放：返回原工单，不增加记录。
93		again, replay, err := s.report("EQ-1", "卡纸", "req-1")
94		if err != nil || !replay || again.ID != tk.ID {
95			t.Fatalf("重放应返回原工单: %v replay=%v err=%v", again, replay, err)
96		}
97		if len(s.data.Tickets) != 1 || len(s.data.Requests) != 1 {
98			t.Fatalf("重放不应增加记录: tickets=%d requests=%d", len(s.data.Tickets), len(s.data.Requests))
99		}
100	
101		// 同一标识搭配不同描述或不同资产必须拒绝。
102		if _, _, err := s.report("EQ-1", "不同故障", "req-1"); !errors.Is(err, errConflict) {
103			t.Fatalf("同标识不同描述应拒绝，得到 %v", err)
104		}
105		if _, err := s.registerAsset("EQ-2", "空调", "二楼"); err != nil {
106			t.Fatal(err)
107		}
108		if _, _, err := s.report("EQ-2", "卡纸", "req-1"); !errors.Is(err, errConflict) {
109			t.Fatalf("同标识不同资产应拒绝，得到 %v", err)
110		}
111	
112		// 关闭工单，设备恢复可用。
113		closed, asset, err := s.closeTicket(tk.ID, "已更换搓纸轮")
114		if err != nil {
115			t.Fatalf("closeTicket: %v", err)
116		}
117		if closed.Status != ticketClosed || asset.Status != statusAvailable {
118			t.Fatalf("关闭后状态异常: ticket=%s asset=%s", closed.Status, asset.Status)
119		}
120	
121		// 重复关闭失败。
122		if _, _, err := s.closeTicket(tk.ID, "再来一次"); !errors.Is(err, errConflict) {
123			t.Fatalf("重复关闭应失败，得到 %v", err)
124		}
125	
126		// 关闭后重放原请求：仍返回原工单及其当前状态，不重开。
127		old, replay, err := s.report("EQ-1", "卡纸", "req-1")
128		if err != nil || !replay || old.ID != tk.ID || old.Status != ticketClosed {
129			t.Fatalf("关闭后重放应返回原已关闭工单: %v replay=%v err=%v", old, replay, err)
130		}
131		if s.findAsset("EQ-1").Status != statusAvailable {
132			t.Fatal("重放不应改动资产状态")
133		}
134	
135		// 资产可用后可用新请求开新工单。
136		tk2, replay, err := s.report("EQ-1", "无法开机", "req-3")
137		if err != nil || replay || tk2.ID != "T0002" {
138			t.Fatalf("新报修应开出 T0002: %v replay=%v err=%v", tk2, replay, err)
139		}
140	
141		// 旧请求重放不影响新单。
142		old, replay, _ = s.report("EQ-1", "卡纸", "req-1")
143		if old.ID != "T0001" || old.Status != ticketClosed || !replay {
144			t.Fatalf("旧请求重放应返回 T0001/已关闭，得到 %v/%v replay=%v", old.ID, old.Status, replay)
145		}
146		if got := s.openTicketOf("EQ-1"); got == nil || got.ID != "T0002" {
147			t.Fatalf("新工单 T0002 应仍为未关闭，得到 %v", got)
148		}
149	
