```go
// validateConsistency 校验整份业务数据的内部一致性……
func validateConsistency(d *storeData) error {
    ticketsByID := map[string]*Ticket{}
    maxUsed := 0
    for _, t := range d.Tickets {
        n, ok := parseTicketSeq(t.ID)
        if !ok {
            return fmt.Errorf("计数器矛盾：工单编号 %q 不是 T 加补零正整数序号的形式", t.ID)
        }
        ticketsByID[t.ID] = t
        if n > maxUsed { maxUsed = n }
    }
    if d.NextTicketSeq < 1 || d.NextTicketSeq <= maxUsed {
        return fmt.Errorf("计数器矛盾：下一工单序号 %d 必须为正且大于全部已用序号（最大已用 %d）", d.NextTicketSeq, maxUsed)
    }
    // 请求绑定
    bound := map[string]int{} // ticketID -> count
    for _, r := range d.Requests {
        t := ticketsByID[r.TicketID]
        if t == nil { continue } // 结构校验已报
        bound[r.TicketID]++
        if r.RequestID != t.RequestID || r.AssetID != t.AssetID || r.Description != t.Description {
            return fmt.Errorf("请求绑定矛盾：请求标识 %q 的绑定与工单 %s 的请求标识、资产编号或故障描述不一致", r.RequestID, t.ID)
        }
    }
    for _, t := range d.Tickets {
        if bound[t.ID] == 0 {
            return fmt.Errorf("请求绑定矛盾：工单 %s 缺少对应的报修请求绑定", t.ID)
        }
        if bound[t.ID] > 1 {
            return fmt.Errorf("请求绑定矛盾：工单 %s 对应多条报修请求绑定", t.ID)
        }
    }
    // 状态
    openByAsset := map[string]string{}
    for _, t := range d.Tickets {
        if t.Status == ticketOpen {
            if t.Result != "" || t.ClosedAt != "" {
                return fmt.Errorf("状态矛盾：未关闭工单 %s 带有维修结果或关闭时间", t.ID)
            }
            if prev, ok := openByAsset[t.AssetID]; ok {
                return fmt.Errorf("状态矛盾：资产 %s 同时存在多张未关闭工单（%s、%s）", t.AssetID, prev, t.ID)
            }
            openByAsset[t.AssetID] = t.ID
        }
    }
    for _, a := range d.Assets {
        _, hasOpen := openByAsset[a.ID]
        if hasOpen && a.Status != statusRepairing {
            return fmt.Errorf("状态矛盾：资产 %s 有未关闭工单但状态为 %q", a.ID, a.Status)
        }
        if !hasOpen && a.Status != statusAvailable {
            return fmt.Errorf("状态矛盾：资产 %s 无未关闭工单但状态为 %q", a.ID, a.Status)
        }
    }
    // 履历
    seenSeq := map[int]string{}
    reportCount := map[string]int{}
    closeCount := map[string]int{}
    events := make([]eventJSON, len(d.EventsJSON))
    copy(events, d.EventsJSON)
    sort.SliceStable(events, func(i, j int) bool { return events[i].Seq < events[j].Seq })
    openByAssetReplay := map[string]string{}
    for _, e := range events {
        if e.Seq < 1 {
            return fmt.Errorf("履历矛盾：履历序号 %d 不是正整数", e.Seq)
        }
        if _, dup := seenSeq[e.Seq]; dup {
            return fmt.Errorf("履历矛盾：履历序号 %d 重复", e.Seq)
        }
        seenSeq[e.Seq] = e.TicketID
        t := ticketsByID[e.TicketID]
        if t == nil { continue }
        if e.AssetID != t.AssetID {
            return fmt.Errorf("履历矛盾：履历（序号 %d）的资产 %s 与工单 %s 所属资产 %s 不一致", e.Seq, e.AssetID, t.ID, t.AssetID)
        }
        switch e.Kind {
        case eventReport:
            reportCount[t.ID]++
            if e.Content != t.Description {
                return fmt.Errorf("履历矛盾：工单 %s 的报修履历内容与故障描述不一致", t.ID)
            }
            if prev, ok := openByAssetReplay[t.AssetID]; ok {
                return fmt.Errorf("履历矛盾：资产 %s 的上一张工单 %s 尚未关闭就产生工单 %s 的报修", t.AssetID, prev, t.ID)
            }
            openByAssetReplay[t.AssetID] = t.ID
        case eventClose:
            closeCount[t.ID]++
            if e.Content != t.Result {
                return fmt.Errorf("履历矛盾：工单 %s 的关闭履历内容与维修结果不一致", t.ID)
            }
            if openByAssetReplay[t.AssetID] != t.ID {
                return fmt.Errorf("履历矛盾：工单 %s 的关闭履历出现在其报修之前", t.ID)
            }
            delete(openByAssetReplay, t.AssetID)
        }
    }
    for _, t := range d.Tickets {
        if reportCount[t.ID] != 1 {
            return fmt.Errorf("履历矛盾：工单 %s 应有恰一条报修履历，实际 %d 条", t.ID, reportCount[t.ID])
        }
        if t.Status == ticketClosed {
            if closeCount[t.ID] != 1 {
                return fmt.Errorf("履历矛盾：已关闭工单 %s 应有恰一条关闭履历，实际 %d 条", t.ID, closeCount[t.ID])
            }
        } else if closeCount[t.ID] != 0 {
            return fmt.Errorf("履历矛盾：未关闭工单 %s 不应有关闭履历", t.ID)
        }
    }
    // 履历推进得到的未关闭工单须与保存状态相符
    for assetID, tid := range openByAssetReplay {
        if openByAsset[assetID] != tid {
            return fmt.Errorf("状态矛盾：按履历推进资产 %s 的未关闭工单为 %s，与保存的状态不符", assetID, tid)
        }
    }
    for assetID, tid := range openByAsset {
        if openByAssetReplay[assetID] != tid {
            return fmt.Errorf("状态矛盾：保存的未关闭工单 %s 与资产 %s 的履历推进结果不符", tid, assetID)
        }
    }
    return nil
}
```

