```go
func parseTicketSeq(id string) (int, bool) {
    if len(id) < 5 || id[0] != 'T' { return 0, false } // 至少 T0001
    for _, c := range id[1:] { if c < '0' || c > '9' { return 0, false } }
    n, err := strconv.Atoi(id[1:])
    if err != nil || n < 1 { return 0, false }
    if id != fmt.Sprintf("T%04d", n) { return 0, false }
    return n, true
}
```

